import java.util.*;

class Solution {
    private int towers = 0;

    public int minCameraCover(TreeNode root) {
        if (dfs(root) == 0) towers++; // root still unwatched
        return towers;
    }

    // 0 = needs cover, 1 = covered without tower, 2 = has tower
    private int dfs(TreeNode n) {
        if (n == null) return 1;
        int a = dfs(n.left), b = dfs(n.right);
        if (a == 0 || b == 0) { towers++; return 2; } // a child needs us
        if (a == 2 || b == 2) return 1;               // watched by a child
        return 0;                                     // let the parent handle it
    }
}

