function minCameraCover(root) {
  // tree DP: [tower here, covered by a child, needs parent]
  const INF = 1e9;
  const go = (n) => {
    if (!n) return [INF, 0, 0];
    const L = go(n.left), R = go(n.right);
    const mL = Math.min(...L), mR = Math.min(...R);
    const t = 1 + mL + mR;
    const c = Math.min(L[0] + Math.min(R[0], R[1]), R[0] + Math.min(L[0], L[1]));
    const u = L[1] + R[1];
    return [t, c, u];
  };
  const r = go(root); return Math.min(r[0], r[1]);
}
